"""End-to-end test of p0d and owner-issuer against the replica of the live kernel and a pg_fence target."""
import json, os, subprocess, sys, time, uuid, threading, urllib.request
import http.server as hs
import psycopg
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey
from cryptography.hazmat.primitives import serialization
BIN = "/home/claude/density-services/target/release"; PG = dict(host="/tmp", port=5544)
R = []
def check(name, ok, detail=""): R.append({"test": name, "pass": bool(ok), "detail": detail}); print(("PASS " if ok else "FAIL ") + name + (f"  [{detail}]" if detail else ""), flush=True)
def keygen(b): return json.loads(subprocess.run([f"{BIN}/{b}", "keygen"], capture_output=True, text=True).stdout)
def http(method, url, body=None):
    req = urllib.request.Request(url, data=json.dumps(body).encode() if body is not None else None, method=method, headers={"content-type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=20) as r: return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e: return e.code, json.loads(e.read() or b"null")
def wait(url):
    for _ in range(50):
        try: urllib.request.urlopen(url, timeout=1); return
        except Exception: time.sleep(0.2)

# ---- key ceremony and enrolment (public keys only) ----
kp, ko = keygen("p0d"), keygen("owner-issuer")
with psycopg.connect(**PG, user="postgres", dbname="acme_fence_ledger", autocommit=True) as c:
    c.execute("delete from issuers"); c.execute("update state set authority_epoch = 1")
    c.execute("insert into issuers values ('p0d',%s,1,'active'),('owner-policy',%s,1,'active')", (bytes.fromhex(kp["pubkey_hex_enrol"]), bytes.fromhex(ko["pubkey_hex_enrol"])))
VER_ID = 'e2e-verifier-' + uuid.uuid4().hex[:8]
ver = Ed25519PrivateKey.generate(); ver_pub = ver.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
with psycopg.connect(**PG, user="postgres", dbname="uap_root_replica", autocommit=True) as c:
    c.execute("insert into p0.keys (key_id, role, process, pubkey, administrator) values (%s,'VERIFIER','verifierd',%s,'e2e')", (VER_ID, ver_pub))
check("key ceremony: two keypairs generated by the binaries; only public keys enrolled", len(kp["pubkey_hex_enrol"]) == 64 and len(ko["pubkey_hex_enrol"]) == 64)

# ---- start services ----
procs = []
def start(binary, env):
    p = subprocess.Popen([f"{BIN}/{binary}"], env={**os.environ, **env}, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE); procs.append(p); return p
owner = start("owner-issuer", {"OWNER_KEY_SEED": ko["seed_hex_store_as_secret"], "P0D_PUBKEY": kp["pubkey_hex_enrol"], "ALLOWED_AUDIENCES": "pg://acme/crm", "LISTEN": "127.0.0.1:8081"})
dburl = "host=127.0.0.1 port=5544 user=p0d password=p0d dbname=uap_root_replica sslmode=require"
p0d = start("p0d", {"PG_SSLMODE": "require", "DATABASE_URL": dburl, "P0D_KEY_SEED": kp["seed_hex_store_as_secret"], "OWNER_ISSUER_ADDR": "127.0.0.1:8081", "OWNER_ISSUER_PUBKEY": ko["pubkey_hex_enrol"], "LISTEN": "127.0.0.1:8080"})
wait("http://127.0.0.1:8080/v1/health"); wait("http://127.0.0.1:8081/v1/pubkey")
try:
    s, h = http("GET", "http://127.0.0.1:8080/v1/health"); check("health: kernel reads the ledger epoch", s == 200 and h["authority_epoch"] == "1", json.dumps(h))
    with psycopg.connect(**PG, user="postgres", dbname="uap_root_replica", autocommit=True) as c:
        tls = c.execute("select s.ssl, s.version from pg_stat_ssl s join pg_stat_activity a using (pid) where a.usename = 'p0d' and a.datname = 'uap_root_replica' limit 1").fetchone()
    check("kernel's database connection is TLS-encrypted (pg_stat_ssl)", tls is not None and tls[0] is True, str(tls))
    s, pk = http("GET", "http://127.0.0.1:8080/v1/pubkey"); check("public key endpoint matches the ceremony", pk["pubkey"] == kp["pubkey_hex_enrol"])

    # ---- events through the single admission path ----
    stream = str(uuid.uuid4()); e1 = {"event_id": str(uuid.uuid4()), "event_kind": "node:(none)->PROPOSED", "stream_id": stream, "subject_type": "node", "subject_id": "e2e-node",
          "payload": {"name": "e2e-node-" + stream[:8]}, "authority_epoch": "1", "expected_revision": "0"}
    s, d = http("POST", "http://127.0.0.1:8080/v1/events", e1); check("event: node proposal accepted (200)", s == 200 and d["decision"] == "ACCEPT", d.get("reason", "")); head = d.get("event_digest")
    s, d = http("POST", "http://127.0.0.1:8080/v1/events", e1); check("event: exact resubmission is a replay", d["decision"] == "REPLAY" and d["event_digest"] == head)
    adm = {"event_id": str(uuid.uuid4()), "event_kind": "node:PROPOSED->ADMITTED", "stream_id": stream, "subject_type": "node", "subject_id": "e2e-node",
           "authority_epoch": "1", "expected_revision": "1", "expected_predecessor": head}
    s, d = http("POST", "http://127.0.0.1:8080/v1/events", adm); check("event: admission without a verifier receipt is deferred (202)", s == 202 and d["reason"] == "MISSING_REQUIRED_GUARD")
    with psycopg.connect(**PG, user="postgres", dbname="uap_root_replica", autocommit=True) as c:
        msg = c.execute("select p0.receipt_message(%s, %s, p0.event_identity(%s::jsonb))", (adm["event_kind"], stream, json.dumps(adm))).fetchone()[0]
    s, d = http("POST", "http://127.0.0.1:8080/v1/events", {**adm, "expected_revision": "0", "receipts": [{"role": "VERIFIER", "key_id": VER_ID, "sig": ver.sign(bytes(msg)).hex()}]})
    check("event: stale revision rejected (409)", s == 409 and d["reason"] == "STALE_REVISION")
    s, d = http("POST", "http://127.0.0.1:8080/v1/events", {**adm, "receipts": [{"role": "VERIFIER", "key_id": VER_ID, "sig": ver.sign(bytes(msg)).hex()}]})
    check("event: admission with a valid verifier receipt accepted", d["decision"] == "ACCEPT" and d["state"] == "ADMITTED")

    # ---- concurrency over HTTP: eight clients, one revision ----
    cs = str(uuid.uuid4()); s, d = http("POST", "http://127.0.0.1:8080/v1/events", {"event_id": str(uuid.uuid4()), "event_kind": "conformance:(none)->OPEN", "stream_id": cs, "subject_type": "conformance", "subject_id": "e2e-race", "payload": {"run": "e2e"}, "authority_epoch": "1", "expected_revision": "0"})
    h0 = d["event_digest"]; results = []
    def racer(i): results.append(http("POST", "http://127.0.0.1:8080/v1/events", {"event_id": str(uuid.uuid4()), "event_kind": "conformance:OPEN->OPEN", "stream_id": cs, "subject_type": "conformance", "subject_id": "e2e-race", "payload": {"racer": i}, "authority_epoch": "1", "expected_revision": "1", "expected_predecessor": h0})[1])
    ts = [threading.Thread(target=racer, args=(i,)) for i in range(8)]; [t.start() for t in ts]; [t.join() for t in ts]
    acc = sum(r["decision"] == "ACCEPT" for r in results); stale = sum(r.get("reason") == "STALE_REVISION" for r in results)
    check("concurrency: eight HTTP clients on one revision, exactly one accepted", acc == 1 and stale == 7, f"accept={acc} stale={stale}")

    # ---- grants: two issuers, verified by pg_fence at the target ----
    with psycopg.connect(**PG, user="postgres", dbname="acme_crm", autocommit=True) as c:
        pre = c.execute("select fence.row_digest('public.orders','3')").fetchone()[0]; hh = c.execute("select fence.history_head('public.orders','3')").fetchone()[0]
        cur = c.execute("select status from orders where id = 3").fetchone()[0]
    req = {"audience": "pg://acme/crm", "effect": {"kind": "update", "table": "public.orders", "pk": "3"}, "prestate_digest": pre, "history_head": hh, "intent": "e2e status change", "ttl_s": 120}
    s, d = http("POST", "http://127.0.0.1:8080/v1/grants", req); g = d.get("grant")
    def vsig(pub, grant, issuer):
        m = b"CFP-SIGNING-INPUT/1" + b"".join(len(x.encode()).to_bytes(8, "big") + x.encode() for x in [grant["v"], grant["grant_id"], grant["audience"], grant["effect"]["kind"], grant["effect"]["table"], grant["effect"]["pk"], grant["prestate"]["digest"], grant["history"]["head"], grant["authority_epoch"], grant["intent"], grant["not_before"], grant["not_after"], str(grant["quorum"]["t"])])
        sig = next(x["sig"] for x in grant["signatures"] if x["issuer"] == issuer)
        try: Ed25519PublicKey.from_public_bytes(bytes.fromhex(pub)).verify(bytes.fromhex(sig), m); return True
        except Exception: return False
    check("grant issued with two signatures, each independently verified", s == 200 and g and len(g["signatures"]) == 2 and vsig(kp["pubkey_hex_enrol"], g, "p0d") and vsig(ko["pubkey_hex_enrol"], g, "owner-policy"))
    new_status = 1 if cur != 1 else 2
    def fenced(grant, status):
        try:
            with psycopg.connect(**PG, user="acme_app", password="a", dbname="acme_crm") as c:
                c.execute("select fence.begin(%s::jsonb)", (json.dumps(grant),)); c.execute("update orders set status = %s where id = 3", (status,)); c.commit(); return "OK"
        except psycopg.Error as e: return e.diag.message_primary
    check("pg_fence at the target accepts the Rust-issued grant", fenced(g, new_status) == "OK")
    check("pg_fence refuses replay of the same grant", fenced(g, new_status) == "CFP_REPLAY")
    single = json.loads(json.dumps(g)); single["signatures"] = [x for x in single["signatures"] if x["issuer"] == "p0d"]
    r_single = fenced(single, new_status); check("a grant stripped to the kernel's signature alone is refused by the fence", r_single == "CFP_QUORUM", r_single)

    # ---- refusals ----
    s, d = http("POST", "http://127.0.0.1:8080/v1/grants", {**req, "audience": "pg://other/db"}); check("p0d returns no grant when the owner-issuer refuses an audience", s == 409 and d["detail"]["reason"] == "AUDIENCE_NOT_ALLOWED" and "grant" not in d)
    s, d = http("POST", "http://127.0.0.1:8080/v1/grants", {**req, "ttl_s": 3600}); check("p0d refuses a validity window beyond policy", d["reason"] == "TTL_OUT_OF_RANGE")
    forged = json.loads(json.dumps(g)); forged["grant_id"] = str(uuid.uuid4()); forged["signatures"] = [{"issuer": "p0d", "root_gen": 1, "sig": Ed25519PrivateKey.generate().sign(b"x").hex()}]
    s, d = http("POST", "http://127.0.0.1:8081/v1/cosign", {"grant": forged}); check("owner-issuer refuses a grant not signed by the kernel", s == 403 and d["reason"] == "NOT_SIGNED_BY_KERNEL")
    long_g = json.loads(json.dumps(g)); long_g["signatures"] = []; long_g["not_after"] = "2099-01-01T00:00:00+00:00"
    s, d = http("POST", "http://127.0.0.1:8081/v1/cosign", {"grant": long_g}); check("owner-issuer refuses an over-long window", s == 403 and d["reason"] == "TTL_TOO_LONG")

    # ---- quorum unavailable and a bad co-signer ----
    owner.terminate(); owner.wait(timeout=5)
    s, d = http("POST", "http://127.0.0.1:8080/v1/grants", req); check("owner-issuer down: p0d defers with QUORUM_UNAVAILABLE and issues nothing", s == 503 and d["reason"] == "QUORUM_UNAVAILABLE" and "grant" not in d)
    class Bad(hs.BaseHTTPRequestHandler):
        def log_message(self, *a): pass
        def do_POST(self):
            self.rfile.read(int(self.headers["content-length"])); body = json.dumps({"issuer": "owner-policy", "root_gen": 1, "sig": Ed25519PrivateKey.generate().sign(b"y").hex()}).encode()
            self.send_response(200); self.send_header("content-length", str(len(body))); self.end_headers(); self.wfile.write(body)
    bad = hs.ThreadingHTTPServer(("127.0.0.1", 8091), Bad); threading.Thread(target=bad.serve_forever, daemon=True).start()
    p0d2 = start("p0d", {"DATABASE_URL": dburl, "P0D_KEY_SEED": kp["seed_hex_store_as_secret"], "OWNER_ISSUER_ADDR": "127.0.0.1:8091", "OWNER_ISSUER_PUBKEY": ko["pubkey_hex_enrol"], "LISTEN": "127.0.0.1:8090"})
    wait("http://127.0.0.1:8090/v1/health")
    s, d = http("POST", "http://127.0.0.1:8090/v1/grants", req); check("p0d rejects a co-signature that does not verify", d["reason"] == "COSIGNATURE_INVALID" and "grant" not in d)
    bad.shutdown()
finally:
    for p in procs:
        if p.poll() is None: p.terminate()
passed = sum(r["pass"] for r in R); print(f"\n{passed}/{len(R)} passed"); json.dump(R, open("/home/claude/density-services/tests/e2e_results.json", "w"), indent=2)
